en.css:
/* ==== shared:start: also used by the legal pages (scripts/build.js copies this block) ==== */
  :root{
    --paper:#FBFCFA;      /* page */
    --pad:#E9F2E4;        /* engineering computation pad */
    --grid:#C7DDBE;       /* pad grid lines */
    --graphite:#232A2A;   /* text */
    --muted:#55605E;      /* secondary text */
    --ink:#1C4C9E;        /* ink blue: links, CTA, annotations */
    --ink-dark:#143A7A;
    --hi:#F6E15A;         /* highlighter, used once per screen */
    --rule:#D5DED2;
    --display:"Bricolage Grotesque", system-ui, sans-serif;
    --body:"Atkinson Hyperlegible", system-ui, sans-serif;
    --hand:"Kalam", "Comic Neue", cursive;
    --wrap:1120px;
  }
  *{box-sizing:border-box}
  html{scroll-behavior:smooth;scroll-padding-top:68px} /* keeps anchors and keyboard focus clear of the sticky header */
  @media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
  section[id]{scroll-margin-top:12px} /* + the 68px scroll-padding above = header (69px) + ~12px, e.g. after the EN/ES switch lands on #rates */
  body{margin:0;background:var(--paper);color:var(--graphite);font:400 1.0625rem/1.6 var(--body);-webkit-font-smoothing:antialiased}
  img,svg{display:block;max-width:100%}
  a{color:var(--ink)}
  :focus-visible{outline:3px solid var(--ink);outline-offset:3px;border-radius:4px}
  .wrap{max-width:var(--wrap);margin:0 auto;padding:0 24px}
  .skip{position:absolute;left:-999px;top:8px;background:var(--graphite);color:#fff;padding:8px 12px;border-radius:6px;z-index:50}
  .skip:focus{left:8px}
  .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

  h1,h2,h3{font-family:var(--display);line-height:1.08;letter-spacing:-.015em;margin:0}
  h1{font-size:clamp(2.2rem,4.2vw,3.25rem);font-weight:800}
  h2{font-size:clamp(1.8rem,3.2vw,2.5rem);font-weight:700}
  h3{font-size:1.4rem;font-weight:700}
  p{margin:0}
  .lede{font-size:1.2rem;color:var(--muted);max-width:34em}

  /* pad texture: the engineering computation paper grid */
  .pad{background-color:var(--pad);
    background-image:
      linear-gradient(var(--grid) 1px,transparent 1px),
      linear-gradient(90deg,var(--grid) 1px,transparent 1px);
    background-size:22px 22px;background-position:-1px -1px}

  /* buttons */
  .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;font:700 1rem/1 var(--body);
    padding:15px 22px;border-radius:8px;text-decoration:none;border:2px solid var(--ink);cursor:pointer}
  .btn-primary{background:var(--ink);color:#fff}
  .btn-ghost{background:transparent;color:var(--ink)}
  /* hover states (pointer devices only, so a tap on a phone doesn't leave a "stuck" hover).
     Primary: darker ink, white text. Outline buttons and chips: pad-green fill, dark ink. Never the highlighter. */
  .btn,.chip{transition:background-color .15s,border-color .15s,color .15s}
  @media (hover:hover){
    .btn-primary:hover{background:var(--ink-dark);border-color:var(--ink-dark);color:#fff}
    .btn-ghost:hover{background:var(--pad);border-color:var(--ink-dark);color:var(--ink-dark)}
    .chip:not([aria-pressed="true"]):not([aria-selected="true"]):hover{background:var(--pad);border-color:var(--ink-dark);color:var(--ink-dark)}
    .chip[aria-pressed="true"]:hover,.chip[aria-selected="true"]:hover{background:var(--ink-dark);border-color:var(--ink-dark);color:#fff}
  }
  @media (prefers-reduced-motion:reduce){.btn,.chip{transition:none}}
  /* text links in the page: darker ink on hover (buttons, chips and the WhatsApp float keep their own colors) */
  main a:not(.btn):not(.ibtn):not(.chip):not(.wa-float):hover{color:var(--ink-dark)}

  /* header */
  .site-head{position:sticky;top:0;z-index:20;background:rgba(251,252,250,.94);backdrop-filter:blur(6px);border-bottom:1px solid var(--rule)}
  .head-in{display:flex;align-items:center;gap:24px;height:68px}
  .mark{font:800 1.25rem/1 var(--display);color:var(--graphite);text-decoration:none;letter-spacing:-.02em;margin-right:auto}
  .mark small{display:block;font:400 .78rem/1.2 var(--body);color:var(--muted);letter-spacing:0;margin-top:3px}
  .nav{display:flex;gap:22px}
  .nav a{color:var(--graphite);text-decoration:none;font-size:.97rem}
  .nav a:hover{color:var(--ink);text-decoration:underline;text-underline-offset:4px}
  .lang{display:inline-flex;border:1.5px solid var(--graphite);border-radius:7px;overflow:hidden}
  .lang a{font:700 .85rem/1 var(--body);padding:8px 11px;color:var(--graphite);text-decoration:none}
  .lang a:hover{background:var(--pad)}
  .lang a[aria-current="page"]{background:var(--graphite);color:#fff}
  .head-cta{padding:11px 16px;font-size:.95rem}
  @media (max-width:920px){.nav{display:none}}
  @media (max-width:560px){.head-cta{display:none}.mark small{display:none}}
  @media (max-width:380px){.mark{font-size:1.08rem}.head-in{gap:14px}}
  /* Six nav links (Resources added): the labels never wrap. Spanish, whenever the nav shows: the short CTA
     label, a tighter nav and no subtitle (the longer labels don't fit the 1120px column otherwise).
     English: the same below ~1100px. */
  .nav a,.head-cta,.mark{white-space:nowrap}
  .site-head .lang,.head-cta{flex:none}
  @media (min-width:921px) and (max-width:1040px){.head-in{gap:16px}.nav{gap:12px !important}.nav a{font-size:.92rem}}
  .cta-mini{display:none}
  @media (min-width:921px){
    html[lang="es"] .head-cta .cta-full,html[lang="es"] .mark small{display:none}
    html[lang="es"] .head-cta .cta-mini{display:inline}
    html[lang="es"] .nav{gap:16px}
  }
  @media (min-width:921px) and (max-width:1099px){
    html[lang="en"] .head-cta .cta-full,html[lang="en"] .mark small{display:none}
    html[lang="en"] .head-cta .cta-mini{display:inline}
    html[lang="en"] .nav{gap:16px}
  }

  /* floating WhatsApp */
  .wa-float{position:fixed;right:18px;bottom:18px;z-index:30;display:inline-flex;align-items:center;gap:9px;
    background:#17744A;color:#fff;text-decoration:none;font:700 1rem/1 var(--body);padding:14px 18px 14px 15px;border-radius:999px;
    box-shadow:0 10px 24px -8px rgba(10,40,25,.55);transition:opacity .2s,transform .2s,visibility .2s}
  .wa-float:hover{background:#0F5E3A}
  .wa-float svg{width:22px;height:22px;flex:none}
  .wa-float.is-hidden{opacity:0;transform:translateY(12px);pointer-events:none;visibility:hidden} /* hidden = not focusable either */
  @media (prefers-reduced-motion:reduce){.wa-float{transition:none}}
  @media (max-width:520px){.wa-float{right:14px;bottom:14px}}

  /* ---- footer-css:start (also copied into www/404.html by the build) ---- */
  .site-foot{border-top:1.5px solid var(--graphite);background:#fff;color:var(--muted);font-size:.95rem}
  .foot-grid{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:22px 32px;padding-top:30px;padding-bottom:34px}
  .foot-h{font:700 1.05rem/1.2 var(--display);color:var(--graphite);letter-spacing:-.01em;margin:0 0 8px}
  .site-foot p{margin:2px 0}
  .foot-list,.legal-links{list-style:none;margin:0;padding:0}
  .site-foot a{display:inline-block;min-height:24px;padding:2px 0;font-weight:700}
  .legal-links{display:flex;flex-wrap:wrap;align-items:center}
  .legal-links li + li::before{content:"\00B7";color:var(--muted);padding:0 8px}
  .legal-links a[aria-current="page"]{color:var(--graphite);text-decoration:none;border-bottom:2px solid var(--ink)}
  /* contact rows: icon + label + detail, one full-width link each */
  .contact-rows{margin-bottom:6px}
  .contact-rows li{border-bottom:1px solid #E3EDDD}
  .contact-rows li:last-child{border-bottom:0} /* hidden rows are removed, so the last visible row is last */
  .site-foot .contact-row{display:flex;align-items:center;gap:14px;min-height:56px;padding:8px 0;font-weight:400;text-decoration:none;color:var(--graphite)}
  .contact-ic{flex:none;display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%;
    background:var(--pad);border:1px solid var(--grid);color:var(--ink)}
  .contact-ic svg{width:22px;height:22px}
  .contact-txt{display:flex;flex-direction:column;min-width:0}
  .contact-label{font:700 1rem/1.3 var(--body);color:var(--ink);text-underline-offset:3px}
  .contact-detail{font-size:.875rem;line-height:1.35;color:#4D5656;overflow-wrap:anywhere} /* 7.5:1 on white */
  .contact-row:hover .contact-label,.contact-row:focus-visible .contact-label{text-decoration:underline}
  .site-foot .contact-row:focus-visible{outline:3px solid var(--ink);outline-offset:2px;border-radius:6px}
  .fine{grid-column:1/-1;border-top:1px solid var(--rule);padding-top:12px;font-size:.88rem;display:flex;flex-wrap:wrap;gap:2px 10px}
  @media (max-width:1099px){.foot-grid{padding-bottom:96px}} /* room for the floating WhatsApp button: below ~1100px it can reach the fine print */
  @media (max-width:760px){.foot-grid{grid-template-columns:1fr}}
  /* ---- footer-css:end ---- */
  /* language suggestion bar (built by the lang-switch script, never in the HTML). Fixed, so it shifts nothing */
  .lang-bar{position:fixed;left:0;right:0;bottom:0;z-index:40;display:flex;align-items:center;gap:6px 12px;
    background:var(--pad);border-top:1px solid #D3DCD8;padding:6px 6px calc(6px + env(safe-area-inset-bottom)) 16px;
    font:400 .95rem/1.35 var(--body);color:var(--graphite)}
  .lang-bar p{margin:0;flex:1}
  .lang-bar button{min-height:44px;border-radius:8px;font:700 .95rem/1 var(--body);cursor:pointer}
  .lang-bar-go{border:0;background:var(--ink);color:#fff;padding:0 16px}
  .lang-bar-go:hover{background:var(--ink-dark)}
  .lang-bar-x{min-width:44px;border:0;background:none;color:var(--graphite);font-size:1.6rem}
  .lang-bar-x:hover{background:#DCE8D5}
  .lang-bar button:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  @media (min-width:700px){.lang-bar{left:16px;right:16px;bottom:16px;max-width:640px;margin:0 auto;border:1px solid #D3DCD8;border-radius:12px;
    padding:6px 6px 6px 18px;box-shadow:0 10px 24px -12px rgba(35,42,42,.35)}}
  @media (prefers-reduced-motion:no-preference){.lang-bar{animation:lang-bar-in .25s ease-out}}
  @keyframes lang-bar-in{from{opacity:0;transform:translateY(12px)}}
  /* while it shows: the WhatsApp button sits above it, and the page can scroll its last lines clear of it */
  .has-lang-bar .wa-float{bottom:calc(var(--lang-bar-h,64px) + 12px)}
  @media (min-width:700px){.has-lang-bar .wa-float{bottom:18px}} /* centered bar (max 640px) leaves the corner free... */
  @media (min-width:700px) and (max-width:1100px){.has-lang-bar .wa-float{bottom:calc(var(--lang-bar-h,64px) + 12px)}} /* ...only above ~1100px */
  .has-lang-bar{scroll-padding-bottom:calc(var(--lang-bar-h,64px) + 8px)} /* focus and in-page scrolling stop above the bar */
  .has-lang-bar body{padding-bottom:var(--lang-bar-h,64px)}
  /* resource cards: the home page's "Free interactive tools", the library and "Related resources" (/resources/) */
  .tool-cards{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:22px}
  .tool-card a{display:flex;flex-direction:column;height:100%;background:#fff;border:1px solid var(--line,#D3DCD8);border-radius:8px;overflow:hidden;
    color:var(--graphite);text-decoration:none;box-shadow:0 1px 2px rgba(35,42,42,.04),0 6px 18px rgba(35,42,42,.06)}
  .tool-card img{display:block;width:100%;height:auto;aspect-ratio:1200/630;border-bottom:1px solid var(--line,#D3DCD8);background:var(--pad)}
  .tool-card-body{display:flex;flex-direction:column;gap:6px;padding:16px 18px 18px;flex:1}
  .tool-card-sub{font-size:.85rem;font-weight:700;color:var(--ink)}
  .tool-card-title{font:700 1.2rem/1.2 var(--display);letter-spacing:-.01em;margin:0}
  .tool-card-desc{color:var(--muted);font-size:.97rem}
  .tool-levels{display:flex;flex-wrap:wrap;gap:6px;margin-top:auto;padding-top:8px}
  .lvl{font-size:.8rem;font-weight:700;border:1.5px solid var(--grid);background:var(--pad);border-radius:999px;padding:3px 10px}
  .tool-card a:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  @media (hover:hover){.tool-card a:hover{border-color:var(--ink)}.tool-card a:hover .tool-card-title{color:var(--ink)}}
  /* ==== shared:end ==== */

en.analytics:
/* analytics:start (the legal pages reuse this block) */
const track = (event, params) => (window.dataLayer = window.dataLayer || []).push({ event, page_language: LANG, ...params });
document.addEventListener("click", e => {
  const a = e.target.closest && e.target.closest("a[href]");
  if (!a) return;
  const href = a.getAttribute("href"), where = a.id === "wa-float" ? "floating_button" : (a.dataset.loc || (a.closest("footer") ? "footer" : "page"));
  if (a.classList.contains("wa-link") || a.dataset.contact === "whatsapp") track("contact_click", { contact_method: "whatsapp", link_location: where });
  else if (href.startsWith("tel:")) track("contact_click", { contact_method: "phone", link_location: where });
  else if (href.startsWith("mailto:")) track("contact_click", { contact_method: "email", link_location: where });
});
/* analytics:end */

en.langSwitch:
/* lang-switch:start (the legal and exam pages reuse this block)
   switchLanguage(lang): the one place that switches language. It works out the section in view,
   saves the choice in the cookie `lang` (server.js sends a returning lang=es visitor from / and
   /exams/ to the Spanish page and re-sends the cookie from the server so Safari keeps it; the
   privacy policy describes it), builds the other page's URL (query string kept, e.g. ?for=, utm_*,
   plus #section) and goes there. Used by the EN/ES toggle and the language suggestion bar.
   The toggle links stay plain <a href>s that work without this script; errors leave them as they are. */
(function () {
  var pageLang = document.documentElement.lang === "es" ? "es" : "en";
  function link(lang) { return document.querySelector('.lang a[data-lang="' + lang + '"]'); }
  function saveLang(lang) { document.cookie = "lang=" + lang + "; Path=/; Max-Age=31536000; Secure; SameSite=Lax"; }
  function hasLangCookie() { return /(?:^|;\s*)lang=(en|es)(?:;|$)/.test(document.cookie); }

  // The section in view: probe line = bottom of the sticky header (measured) + 25% of the rest of the
  // viewport. The section[id] whose box contains the line; else the last one whose top is above it;
  // none (still in the hero) -> "". Legal pages: the ids are on the headings (data-twin-id = the id on
  // the other page), so their box is the heading's <section>.
  function sectionHash() {
    var head = document.querySelector(".site-head");
    var top = head ? Math.max(0, head.getBoundingClientRect().bottom) : 0;
    var probe = top + (window.innerHeight - top) * 0.25;
    var els = document.querySelectorAll("main section[id], main [data-twin-id]"), inside = "", above = "";
    for (var i = 0; i < els.length; i++) {
      var el = els[i], box = el.tagName === "SECTION" ? el : (el.closest("section") || el);
      if (!box.getClientRects().length) continue; // hidden (e.g. #reviews before there are any)
      var r = box.getBoundingClientRect(), id = el.getAttribute("data-twin-id") || el.id;
      if (r.top <= probe && r.bottom > probe) inside = id;
      if (r.top <= probe) above = id;
    }
    return (inside || above) ? "#" + (inside || above) : "";
  }

  // returns the URL; navigates unless navigate === false (the toggle lets its own link navigate)
  function switchLanguage(lang, navigate) {
    var a = link(lang);
    if (!a || (lang !== "en" && lang !== "es")) return null;
    saveLang(lang);
    var q = new URLSearchParams(location.search);
    q.delete("lang"); // an old ?lang=es would send the English page straight back to Spanish
    q = q.toString();
    var url = a.getAttribute("href").split(/[?#]/)[0] + (q ? "?" + q : "") + sectionHash();
    if (navigate !== false) location.assign(url);
    return url;
  }
  window.switchLanguage = switchLanguage;

  try {
    [].forEach.call(document.querySelectorAll(".lang a[data-lang]"), function (a) {
      a.addEventListener("click", function () {
        try { var url = switchLanguage(a.getAttribute("data-lang"), false); if (url) a.setAttribute("href", url); }
        catch (err) { /* the link still goes to the other page */ }
      });
    });
  } catch (err) {}

  // Language suggestion bar: only with no lang cookie, when the browser's first "en"/"es" language
  // isn't this page's. Rendered here (never in the HTML), never redirects, never takes focus.
  // Accept -> switchLanguage; close (or Esc) -> lang = this page's language. Either way it's gone for good.
  try {
    if (hasLangCookie()) return;
    var want = null, langs = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || ""];
    for (var i = 0; i < langs.length && !want; i++) {
      var l = String(langs[i]).toLowerCase().split("-")[0];
      if (l === "en" || l === "es") want = l;
    }
    if (!want || want === pageLang || !link(want)) return;
    var T = {
      es: { label: "Sugerencia de idioma", text: "¿Prefieres ver esta página en español?", go: "Ver en español", close: "Cerrar" },
      en: { label: "Language suggestion", text: "Prefer to read this page in English?", go: "View in English", close: "Close" }
    }[want];
    var bar = document.createElement("aside");
    bar.className = "lang-bar"; bar.lang = want; bar.setAttribute("aria-label", T.label);
    var p = document.createElement("p"); p.textContent = T.text;
    var go = document.createElement("button"); go.type = "button"; go.className = "lang-bar-go"; go.textContent = T.go;
    var x = document.createElement("button"); x.type = "button"; x.className = "lang-bar-x"; x.setAttribute("aria-label", T.close); x.innerHTML = '<span aria-hidden="true">&times;</span>';
    bar.appendChild(p); bar.appendChild(go); bar.appendChild(x);
    var root = document.documentElement;
    // --lang-bar-h: the space the bar takes from the bottom edge (offsetTop ignores the entry animation)
    var fit = function () { root.style.setProperty("--lang-bar-h", Math.max(0, window.innerHeight - bar.offsetTop) + "px"); };
    var track = function (choice) { (window.dataLayer = window.dataLayer || []).push({ event: "select_content", content_type: "language_suggestion", item_id: choice, page_language: pageLang }); };
    var onKey = function (e) { if (e.key === "Escape" && !e.defaultPrevented) close(); };
    var close = function () {
      saveLang(pageLang); track("dismiss");
      bar.remove(); root.classList.remove("has-lang-bar"); root.style.removeProperty("--lang-bar-h");
      document.removeEventListener("keydown", onKey); window.removeEventListener("resize", fit);
    };
    go.addEventListener("click", function () { track("accept"); switchLanguage(want); });
    x.addEventListener("click", close);
    var show = function () {
      if (bar.isConnected || hasLangCookie()) return;
      document.addEventListener("keydown", onKey);
      window.addEventListener("resize", fit);
      document.body.appendChild(bar);
      fit(); root.classList.add("has-lang-bar");
    };
    // after the web fonts: the bar sits on the bottom edge, so a font swap changing its height would move it (CLS)
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(show, show); else show();
  } catch (err) {}
})();
/* lang-switch:end */

en.resourcesCss:
/* Resources pages (/resources/, /es/recursos/ and each tool's page). scripts/build.js puts this in
   www/resources-shell.json, after the site's shared CSS from www/index.html (tokens, buttons, .pad,
   header, footer, .tool-card). Never the highlighter in the bar; the page's one highlighter is the
   guarantee line at the bottom. */
:root{--bar:44px}
@media (min-width:700px){:root{--bar:48px}}
.crumbs ol{list-style:none;margin:0 0 14px;padding:0;display:flex;flex-wrap:wrap;font-size:.9rem;color:var(--muted)}
.crumbs li + li::before{content:"/";padding:0 .45em}
.crumbs a{color:var(--muted)}

/* ---- tool page: thin bar ---- */
.res-page{background:var(--paper)}
.res-bar{position:sticky;top:0;z-index:20;height:var(--bar);display:flex;align-items:center;gap:4px;padding:0 8px;
  background:var(--pad);border-bottom:1px solid var(--grid)}
.res-mark{font:800 1.05rem/1 var(--display);color:var(--graphite);text-decoration:none;letter-spacing:-.02em;white-space:nowrap;
  min-height:44px;display:inline-flex;align-items:center;padding:0 6px}
.res-mark-short{display:none}
.res-title{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:700 .95rem/1.2 var(--body);color:var(--muted);padding:0 8px}
.res-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-width:44px;min-height:44px;padding:0 10px;
  font:700 .9rem/1 var(--body);color:var(--ink);background:transparent;border:0;border-radius:8px;text-decoration:none;cursor:pointer;white-space:nowrap}
.res-btn svg{width:20px;height:20px;flex:none}
.res-btn[hidden]{display:none}
@media (hover:hover){.res-btn:hover{background:#fff;color:var(--ink-dark)}}
.res-btn:focus-visible,.res-mark:focus-visible,.res-cue:focus-visible{outline:3px solid var(--ink);outline-offset:-3px}
.res-bar .lang{border-width:1.5px;flex:none}
.res-bar .lang a{min-height:41px;display:inline-flex;align-items:center;justify-content:center;min-width:41px;padding:0 9px}
.res-cta{flex:none;min-height:44px;padding:0 14px;font-size:.92rem;margin-left:4px}
.res-cta .cta-mini{display:none}
@media (min-width:700px){.res-bar{padding:0 12px;gap:6px}.res-cta{min-height:40px}}
@media (max-width:899px){.res-title{visibility:hidden;padding:0}.res-lbl{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}}
@media (max-width:599px){
  .res-bar .lang a[aria-current]{display:none}           /* one toggle: the other language */
  .res-bar .lang a{min-width:41px}
  .res-cta .cta-full{display:none}.res-cta .cta-mini{display:inline}
  .res-cta{padding:0 12px;font-size:.88rem}
}
@media (max-width:419px){
  .res-bar{gap:2px;padding:0 4px}
  .res-mark-full{display:none}.res-mark-short{display:inline}
  .res-cta{padding:0 10px;font-size:.85rem;margin-left:2px}
}
.res-preview{margin:0;padding:8px 12px;background:var(--graphite);color:#fff;font-weight:700;font-size:.9rem;text-align:center}

/* ---- tool page: the tool fills the rest of the screen ---- */
.res-stage{position:relative;background:#fff;display:flex;flex-direction:column;height:calc(100vh - var(--bar));height:calc(100dvh - var(--bar))}
.res-stage iframe{flex:1 1 auto;width:100%;min-height:0;border:0;display:block;background:#fff}
.res-stage:fullscreen{height:100vh;height:100dvh}
.res-stage:fullscreen .res-cue{display:none}
.res-stage:-webkit-full-screen{height:100vh}
.res-cue{flex:none;display:flex;align-items:center;justify-content:center;gap:6px;min-height:44px;border-top:1px solid var(--grid);
  background:var(--pad);color:var(--ink);font:700 .92rem/1 var(--body);text-decoration:none}
.res-cue svg{width:18px;height:18px}
@media (hover:hover){.res-cue:hover{color:var(--ink-dark);background:#fff}}
.res-noscript{padding:24px;font-weight:700}

/* ---- tool page: the written part ---- */
.res-wrap{padding-top:40px;padding-bottom:72px}
.res-sheet{max-width:50em;margin-top:0;padding:30px 36px 34px 52px}
.res-sheet h1{font-size:clamp(1.9rem,3.6vw,2.75rem);max-width:22em}
.res-kicker{font-weight:700;color:var(--ink);font-size:.95rem;margin:0 0 10px}
.res-intro{margin-top:16px;font-size:1.12rem;max-width:40em}
.res-intro p + p{margin-top:12px}
.res-sec{margin-top:34px;outline:0}
.res-sec h2{font-size:clamp(1.35rem,2.4vw,1.7rem);margin-bottom:12px}
.res-steps,.res-ideas{margin:0;padding-left:1.4em;max-width:40em}
.res-steps li,.res-ideas li{margin:0 0 10px;padding-left:4px}
.res-steps li::marker{font-weight:700;color:var(--ink)}
.res-ideas li::marker{color:var(--ink)}
.res-sheet .faq{max-width:none}
.res-see-also{margin-top:28px;color:var(--muted)}
.res-see-also a{font-weight:700}
.res-related{margin-top:56px}
.res-related h2,.res-help h2{font-size:clamp(1.5rem,2.8vw,2rem);margin-bottom:18px}
.res-help{margin-top:56px;max-width:46em}
.res-help > p{color:var(--muted);font-size:1.1rem;max-width:38em}
.res-help .guarantee{margin-top:20px}
.res-help-cta{margin-top:24px}
.katex{font-size:1.08em}
.katex-display{overflow-x:auto;overflow-y:hidden;padding:4px 0}
@media (max-width:520px){.res-sheet{padding:22px 18px 24px 30px}.res-wrap{padding-top:28px}}

/* ---- library ---- */
.lib-band{border-bottom:1px solid var(--grid);padding:38px 0 44px}
.lib-band .lede{color:var(--graphite);margin-top:14px;max-width:40em}
.lib{padding:40px 0 88px}
.lib-filters{display:grid;gap:12px;margin-bottom:22px}
.lib-filters[hidden]{display:none}
.lib-filter{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.lib-filter-label{font-size:.9rem;font-weight:700;color:var(--muted);min-width:5em}
.lib-filter .chip[aria-pressed="true"]{background:var(--ink);color:#fff}
.lib-count{color:var(--muted);font-size:.95rem;margin:0 0 16px}
.lib-empty{font-size:1.1rem;color:var(--muted);padding:24px 0}
.lib-empty[hidden]{display:none}
.tool-card[hidden]{display:none}
.lib-filter .chip{font:700 .92rem/1.2 var(--body);color:var(--ink);background:#fff;border:2px solid var(--ink);border-radius:999px;padding:6px 14px;min-height:44px;cursor:pointer}

/* the home page's sheet, FAQ and guarantee styles (they live in its own CSS, not the shared block) */
.note-sheet{position:relative;background:#fff;border:1px solid var(--line);box-shadow:var(--soft-shadow);border-radius:6px}
.faq details{border-bottom:1px solid var(--rule)}
.faq details:first-child{border-top:1px solid var(--rule)}
.faq summary{cursor:pointer;list-style:none;padding:18px 40px 18px 0;font:700 1.08rem/1.35 var(--display);position:relative}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after{content:"+";position:absolute;right:6px;top:14px;font:400 1.6rem/1 var(--body);color:var(--ink)}
.faq details[open] summary::after{content:"\2212"}
.faq details p{padding:0 0 20px;color:var(--muted);max-width:40em}
.guarantee{display:flex;gap:14px;align-items:flex-start;background:#fff;border:1px solid var(--line);box-shadow:var(--soft-shadow);border-radius:6px;padding:20px 24px;max-width:46em}
.check{flex:none;width:26px;height:26px;color:var(--ink)}
.guarantee p{color:var(--muted);font-size:1.02rem}
.guarantee strong{display:inline;color:var(--graphite);background:var(--hi);border-radius:3px;padding:1px 4px;-webkit-box-decoration-break:clone;box-decoration-break:clone}
@media (max-width:520px){.guarantee{padding:16px;gap:12px}}
.res-sheet li .katex-display{margin:.2em 0}
.res-sheet li .katex-display > .katex{text-align:left}

en.resourceJs:
/* A resource page's bar and frame (scripts/build.js inlines it after the analytics and lang-switch
   blocks, so `track` and `LANG` exist). The tool keeps its values in its own #hash; the prelude the
   server injects into the tool posts {source:"jdt-tool", type:"state"|"ready", hash} to this page,
   which mirrors that hash into its own address bar (replaceState: no reload, no history entries).
   Copy link and the EN/ES switch use it, so a shared link opens the same setup. */
(function () {
  var frame = document.getElementById("res-frame");
  if (!frame) return;
  var id = document.body.getAttribute("data-resource-id") || "";
  var status = document.getElementById("res-status");
  var toolHash = window.__jdtToolHash || "";
  var MAX = 2000;

  function say(msg) { if (status) { status.textContent = ""; setTimeout(function () { status.textContent = msg; }, 30); } }
  function baseUrl() {
    var q = new URLSearchParams(location.search);
    q.delete("lang");
    q = q.toString();
    return location.pathname + (q ? "?" + q : "");
  }

  // tool -> page: only messages from this frame's window, with the expected shape
  window.addEventListener("message", function (e) {
    if (e.source !== frame.contentWindow) return;
    var d = e.data;
    if (!d || typeof d !== "object" || d.source !== "jdt-tool" || (d.type !== "state" && d.type !== "ready")) return;
    var h = typeof d.hash === "string" ? d.hash : "";
    if (h.length > MAX || (h && h.charAt(0) !== "#")) return;
    if (h === "#") h = "";
    toolHash = h;
    try { history.replaceState(history.state, "", baseUrl() + h); } catch (err) {}
  });

  // the visitor edits the #hash in the address bar: reload the tool with it (our own replaceState
  // calls never fire hashchange; the page's section anchors aren't tool state)
  window.addEventListener("hashchange", function () {
    var h = location.hash;
    if (h === toolHash || h.length > MAX || /^#(main|tool|how|ideas|faq|related|get-help)$/.test(h)) return;
    toolHash = h;
    frame.src = frame.src.split("#")[0] + h;
  });

  // Copy link: this page with the tool's current setup
  var copy = document.getElementById("res-copy");
  if (copy) {
    var label = copy.querySelector(".res-lbl"), idle = label ? label.textContent : "";
    var done = function (ok) {
      var msg = ok ? copy.getAttribute("data-copied") : copy.getAttribute("data-failed");
      if (label && ok) { label.textContent = msg; setTimeout(function () { label.textContent = idle; }, 2000); }
      copy.classList.toggle("is-done", ok);
      say(msg);
    };
    copy.addEventListener("click", function () {
      var url = location.origin + baseUrl() + toolHash;
      var fallback = function () {
        try {
          var ta = document.createElement("textarea");
          ta.value = url; ta.setAttribute("readonly", ""); ta.style.position = "fixed"; ta.style.opacity = "0";
          document.body.appendChild(ta); ta.select();
          var ok = document.execCommand("copy"); ta.remove(); done(ok);
        } catch (err) { done(false); }
      };
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(function () { done(true); }, fallback);
      else fallback();
      track("resource_link_copy", { resource_id: id, has_state: !!toolHash });
    });
  }

  // Full screen: the tool area (hidden where the Fullscreen API isn't available, e.g. iPhone)
  var fs = document.getElementById("res-fs"), stage = document.getElementById("tool");
  var req = stage && (stage.requestFullscreen || stage.webkitRequestFullscreen);
  var enabled = document.fullscreenEnabled || document.webkitFullscreenEnabled;
  if (fs && req && enabled) {
    fs.hidden = false;
    var enter = fs.getAttribute("aria-label"), exit = fs.getAttribute("data-exit");
    var current = function () { return document.fullscreenElement || document.webkitFullscreenElement; };
    fs.addEventListener("click", function () {
      if (current()) { (document.exitFullscreen || document.webkitExitFullscreen).call(document); return; }
      try { var p = req.call(stage); if (p && p.catch) p.catch(function () {}); } catch (err) {}
      track("resource_fullscreen", { resource_id: id });
    });
    var sync = function () { var on = !!current(); fs.setAttribute("aria-label", on ? exit : enter); fs.title = on ? exit : enter; };
    document.addEventListener("fullscreenchange", sync);
    document.addEventListener("webkitfullscreenchange", sync);
  }

  // EN/ES: the lang-switch block's own click handler runs first and adds a #section; this one runs
  // after it and puts the tool's setup there instead (the two pages show the same tool).
  [].forEach.call(document.querySelectorAll(".res-bar .lang a[data-lang]"), function (a) {
    a.addEventListener("click", function () {
      var q = new URLSearchParams(location.search);
      q.delete("lang");
      q = q.toString();
      a.setAttribute("href", a.getAttribute("href").split(/[?#]/)[0] + (q ? "?" + q : "") + toolHash);
    });
  });

  // "How it works": scroll without touching the #hash (it belongs to the tool)
  var cue = document.querySelector(".res-cue");
  if (cue) cue.addEventListener("click", function (e) {
    var target = document.getElementById("how");
    if (!target) return;
    e.preventDefault();
    var smooth = !(window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches);
    target.scrollIntoView({ behavior: smooth ? "smooth" : "auto", block: "start" });
    try { target.focus({ preventScroll: true }); } catch (err) { target.focus(); }
  });

  // booking clicks (bar and the CTA at the bottom)
  [].forEach.call(document.querySelectorAll('a[data-loc="bar"], a[data-loc="cta"]'), function (a) {
    a.addEventListener("click", function () { track("resource_book_click", { resource_id: id, link_location: a.getAttribute("data-loc") }); });
  });
})();

en.libraryJs:
/* Library filters (/resources/, /es/recursos/): one subject and one level at a time ("All" = no
   filter). The list is server-rendered and complete without this script; the chips only appear with it. */
(function () {
  var box = document.getElementById("lib-filters"), list = document.getElementById("lib-list");
  if (!box || !list) return;
  var count = document.getElementById("lib-count"), none = document.getElementById("lib-nomatch");
  var cards = [].slice.call(list.querySelectorAll(".tool-card"));
  var pick = { subject: "", level: "" };
  function apply() {
    var n = 0;
    cards.forEach(function (c) {
      var ok = (!pick.subject || c.getAttribute("data-subject") === pick.subject) &&
        (!pick.level || (" " + c.getAttribute("data-levels") + " ").indexOf(" " + pick.level + " ") >= 0);
      c.hidden = !ok;
      if (ok) n++;
    });
    if (count) count.textContent = n === 1 ? count.getAttribute("data-one") : count.getAttribute("data-many").replace("{n}", n);
    if (none) none.hidden = n > 0;
  }
  [].forEach.call(box.querySelectorAll("[data-group]"), function (g) {
    var group = g.getAttribute("data-group");
    g.addEventListener("click", function (e) {
      var b = e.target.closest && e.target.closest("button[data-value]");
      if (!b) return;
      pick[group] = b.getAttribute("data-value");
      [].forEach.call(g.querySelectorAll("button"), function (x) { x.setAttribute("aria-pressed", x === b ? "true" : "false"); });
      apply();
    });
  });
  box.hidden = false;
})();

es.css:
/* ==== shared:start: also used by the legal pages (scripts/build.js copies this block) ==== */
  :root{
    --paper:#FBFCFA;      /* page */
    --pad:#E9F2E4;        /* engineering computation pad */
    --grid:#C7DDBE;       /* pad grid lines */
    --graphite:#232A2A;   /* text */
    --muted:#55605E;      /* secondary text */
    --ink:#1C4C9E;        /* ink blue: links, CTA, annotations */
    --ink-dark:#143A7A;
    --hi:#F6E15A;         /* highlighter, used once per screen */
    --rule:#D5DED2;
    --display:"Bricolage Grotesque", system-ui, sans-serif;
    --body:"Atkinson Hyperlegible", system-ui, sans-serif;
    --hand:"Kalam", "Comic Neue", cursive;
    --wrap:1120px;
  }
  *{box-sizing:border-box}
  html{scroll-behavior:smooth;scroll-padding-top:68px} /* keeps anchors and keyboard focus clear of the sticky header */
  @media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
  section[id]{scroll-margin-top:12px} /* + the 68px scroll-padding above = header (69px) + ~12px, e.g. after the EN/ES switch lands on #rates */
  body{margin:0;background:var(--paper);color:var(--graphite);font:400 1.0625rem/1.6 var(--body);-webkit-font-smoothing:antialiased}
  img,svg{display:block;max-width:100%}
  a{color:var(--ink)}
  :focus-visible{outline:3px solid var(--ink);outline-offset:3px;border-radius:4px}
  .wrap{max-width:var(--wrap);margin:0 auto;padding:0 24px}
  .skip{position:absolute;left:-999px;top:8px;background:var(--graphite);color:#fff;padding:8px 12px;border-radius:6px;z-index:50}
  .skip:focus{left:8px}
  .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}

  h1,h2,h3{font-family:var(--display);line-height:1.08;letter-spacing:-.015em;margin:0}
  h1{font-size:clamp(2.2rem,4.2vw,3.25rem);font-weight:800}
  h2{font-size:clamp(1.8rem,3.2vw,2.5rem);font-weight:700}
  h3{font-size:1.4rem;font-weight:700}
  p{margin:0}
  .lede{font-size:1.2rem;color:var(--muted);max-width:34em}

  /* pad texture: the engineering computation paper grid */
  .pad{background-color:var(--pad);
    background-image:
      linear-gradient(var(--grid) 1px,transparent 1px),
      linear-gradient(90deg,var(--grid) 1px,transparent 1px);
    background-size:22px 22px;background-position:-1px -1px}

  /* buttons */
  .btn{display:inline-flex;align-items:center;justify-content:center;gap:.5em;font:700 1rem/1 var(--body);
    padding:15px 22px;border-radius:8px;text-decoration:none;border:2px solid var(--ink);cursor:pointer}
  .btn-primary{background:var(--ink);color:#fff}
  .btn-ghost{background:transparent;color:var(--ink)}
  /* hover states (pointer devices only, so a tap on a phone doesn't leave a "stuck" hover).
     Primary: darker ink, white text. Outline buttons and chips: pad-green fill, dark ink. Never the highlighter. */
  .btn,.chip{transition:background-color .15s,border-color .15s,color .15s}
  @media (hover:hover){
    .btn-primary:hover{background:var(--ink-dark);border-color:var(--ink-dark);color:#fff}
    .btn-ghost:hover{background:var(--pad);border-color:var(--ink-dark);color:var(--ink-dark)}
    .chip:not([aria-pressed="true"]):not([aria-selected="true"]):hover{background:var(--pad);border-color:var(--ink-dark);color:var(--ink-dark)}
    .chip[aria-pressed="true"]:hover,.chip[aria-selected="true"]:hover{background:var(--ink-dark);border-color:var(--ink-dark);color:#fff}
  }
  @media (prefers-reduced-motion:reduce){.btn,.chip{transition:none}}
  /* text links in the page: darker ink on hover (buttons, chips and the WhatsApp float keep their own colors) */
  main a:not(.btn):not(.ibtn):not(.chip):not(.wa-float):hover{color:var(--ink-dark)}

  /* header */
  .site-head{position:sticky;top:0;z-index:20;background:rgba(251,252,250,.94);backdrop-filter:blur(6px);border-bottom:1px solid var(--rule)}
  .head-in{display:flex;align-items:center;gap:24px;height:68px}
  .mark{font:800 1.25rem/1 var(--display);color:var(--graphite);text-decoration:none;letter-spacing:-.02em;margin-right:auto}
  .mark small{display:block;font:400 .78rem/1.2 var(--body);color:var(--muted);letter-spacing:0;margin-top:3px}
  .nav{display:flex;gap:22px}
  .nav a{color:var(--graphite);text-decoration:none;font-size:.97rem}
  .nav a:hover{color:var(--ink);text-decoration:underline;text-underline-offset:4px}
  .lang{display:inline-flex;border:1.5px solid var(--graphite);border-radius:7px;overflow:hidden}
  .lang a{font:700 .85rem/1 var(--body);padding:8px 11px;color:var(--graphite);text-decoration:none}
  .lang a:hover{background:var(--pad)}
  .lang a[aria-current="page"]{background:var(--graphite);color:#fff}
  .head-cta{padding:11px 16px;font-size:.95rem}
  @media (max-width:920px){.nav{display:none}}
  @media (max-width:560px){.head-cta{display:none}.mark small{display:none}}
  @media (max-width:380px){.mark{font-size:1.08rem}.head-in{gap:14px}}
  /* Six nav links (Resources added): the labels never wrap. Spanish, whenever the nav shows: the short CTA
     label, a tighter nav and no subtitle (the longer labels don't fit the 1120px column otherwise).
     English: the same below ~1100px. */
  .nav a,.head-cta,.mark{white-space:nowrap}
  .site-head .lang,.head-cta{flex:none}
  @media (min-width:921px) and (max-width:1040px){.head-in{gap:16px}.nav{gap:12px !important}.nav a{font-size:.92rem}}
  .cta-mini{display:none}
  @media (min-width:921px){
    html[lang="es"] .head-cta .cta-full,html[lang="es"] .mark small{display:none}
    html[lang="es"] .head-cta .cta-mini{display:inline}
    html[lang="es"] .nav{gap:16px}
  }
  @media (min-width:921px) and (max-width:1099px){
    html[lang="en"] .head-cta .cta-full,html[lang="en"] .mark small{display:none}
    html[lang="en"] .head-cta .cta-mini{display:inline}
    html[lang="en"] .nav{gap:16px}
  }

  /* floating WhatsApp */
  .wa-float{position:fixed;right:18px;bottom:18px;z-index:30;display:inline-flex;align-items:center;gap:9px;
    background:#17744A;color:#fff;text-decoration:none;font:700 1rem/1 var(--body);padding:14px 18px 14px 15px;border-radius:999px;
    box-shadow:0 10px 24px -8px rgba(10,40,25,.55);transition:opacity .2s,transform .2s,visibility .2s}
  .wa-float:hover{background:#0F5E3A}
  .wa-float svg{width:22px;height:22px;flex:none}
  .wa-float.is-hidden{opacity:0;transform:translateY(12px);pointer-events:none;visibility:hidden} /* hidden = not focusable either */
  @media (prefers-reduced-motion:reduce){.wa-float{transition:none}}
  @media (max-width:520px){.wa-float{right:14px;bottom:14px}}

  /* ---- footer-css:start (also copied into www/404.html by the build) ---- */
  .site-foot{border-top:1.5px solid var(--graphite);background:#fff;color:var(--muted);font-size:.95rem}
  .foot-grid{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:22px 32px;padding-top:30px;padding-bottom:34px}
  .foot-h{font:700 1.05rem/1.2 var(--display);color:var(--graphite);letter-spacing:-.01em;margin:0 0 8px}
  .site-foot p{margin:2px 0}
  .foot-list,.legal-links{list-style:none;margin:0;padding:0}
  .site-foot a{display:inline-block;min-height:24px;padding:2px 0;font-weight:700}
  .legal-links{display:flex;flex-wrap:wrap;align-items:center}
  .legal-links li + li::before{content:"\00B7";color:var(--muted);padding:0 8px}
  .legal-links a[aria-current="page"]{color:var(--graphite);text-decoration:none;border-bottom:2px solid var(--ink)}
  /* contact rows: icon + label + detail, one full-width link each */
  .contact-rows{margin-bottom:6px}
  .contact-rows li{border-bottom:1px solid #E3EDDD}
  .contact-rows li:last-child{border-bottom:0} /* hidden rows are removed, so the last visible row is last */
  .site-foot .contact-row{display:flex;align-items:center;gap:14px;min-height:56px;padding:8px 0;font-weight:400;text-decoration:none;color:var(--graphite)}
  .contact-ic{flex:none;display:flex;align-items:center;justify-content:center;width:40px;height:40px;border-radius:50%;
    background:var(--pad);border:1px solid var(--grid);color:var(--ink)}
  .contact-ic svg{width:22px;height:22px}
  .contact-txt{display:flex;flex-direction:column;min-width:0}
  .contact-label{font:700 1rem/1.3 var(--body);color:var(--ink);text-underline-offset:3px}
  .contact-detail{font-size:.875rem;line-height:1.35;color:#4D5656;overflow-wrap:anywhere} /* 7.5:1 on white */
  .contact-row:hover .contact-label,.contact-row:focus-visible .contact-label{text-decoration:underline}
  .site-foot .contact-row:focus-visible{outline:3px solid var(--ink);outline-offset:2px;border-radius:6px}
  .fine{grid-column:1/-1;border-top:1px solid var(--rule);padding-top:12px;font-size:.88rem;display:flex;flex-wrap:wrap;gap:2px 10px}
  @media (max-width:1099px){.foot-grid{padding-bottom:96px}} /* room for the floating WhatsApp button: below ~1100px it can reach the fine print */
  @media (max-width:760px){.foot-grid{grid-template-columns:1fr}}
  /* ---- footer-css:end ---- */
  /* language suggestion bar (built by the lang-switch script, never in the HTML). Fixed, so it shifts nothing */
  .lang-bar{position:fixed;left:0;right:0;bottom:0;z-index:40;display:flex;align-items:center;gap:6px 12px;
    background:var(--pad);border-top:1px solid #D3DCD8;padding:6px 6px calc(6px + env(safe-area-inset-bottom)) 16px;
    font:400 .95rem/1.35 var(--body);color:var(--graphite)}
  .lang-bar p{margin:0;flex:1}
  .lang-bar button{min-height:44px;border-radius:8px;font:700 .95rem/1 var(--body);cursor:pointer}
  .lang-bar-go{border:0;background:var(--ink);color:#fff;padding:0 16px}
  .lang-bar-go:hover{background:var(--ink-dark)}
  .lang-bar-x{min-width:44px;border:0;background:none;color:var(--graphite);font-size:1.6rem}
  .lang-bar-x:hover{background:#DCE8D5}
  .lang-bar button:focus-visible{outline:3px solid var(--ink);outline-offset:2px}
  @media (min-width:700px){.lang-bar{left:16px;right:16px;bottom:16px;max-width:640px;margin:0 auto;border:1px solid #D3DCD8;border-radius:12px;
    padding:6px 6px 6px 18px;box-shadow:0 10px 24px -12px rgba(35,42,42,.35)}}
