es.analytics:
/* analytics:start (the legal pages reuse this block) */
const track = (event, params) => (window.dataLayer = window.dataLayer || []).push({ event, page_language: LANG, ...params });
document.addEventListener("click", e => {
  const a = e.target.closest && e.target.closest("a[href]");
  if (!a) return;
  const href = a.getAttribute("href"), where = a.id === "wa-float" ? "floating_button" : (a.dataset.loc || (a.closest("footer") ? "footer" : "page"));
  if (a.classList.contains("wa-link") || a.dataset.contact === "whatsapp") track("contact_click", { contact_method: "whatsapp", link_location: where });
  else if (href.startsWith("tel:")) track("contact_click", { contact_method: "phone", link_location: where });
  else if (href.startsWith("mailto:")) track("contact_click", { contact_method: "email", link_location: where });
});
/* analytics:end */

es.langSwitch:
/* lang-switch:start (the legal and exam pages reuse this block)
   switchLanguage(lang): the one place that switches language. It works out the section in view,
   saves the choice in the cookie `lang` (server.js sends a returning lang=es visitor from / and
   /exams/ to the Spanish page and re-sends the cookie from the server so Safari keeps it; the
   privacy policy describes it), builds the other page's URL (query string kept, e.g. ?for=, utm_*,
   plus #section) and goes there. Used by the EN/ES toggle and the language suggestion bar.
   The toggle links stay plain <a href>s that work without this script; errors leave them as they are. */
(function () {
  var pageLang = document.documentElement.lang === "es" ? "es" : "en";
  function link(lang) { return document.querySelector('.lang a[data-lang="' + lang + '"]'); }
  function saveLang(lang) { document.cookie = "lang=" + lang + "; Path=/; Max-Age=31536000; Secure; SameSite=Lax"; }
  function hasLangCookie() { return /(?:^|;\s*)lang=(en|es)(?:;|$)/.test(document.cookie); }

  // The section in view: probe line = bottom of the sticky header (measured) + 25% of the rest of the
  // viewport. The section[id] whose box contains the line; else the last one whose top is above it;
  // none (still in the hero) -> "". Legal pages: the ids are on the headings (data-twin-id = the id on
  // the other page), so their box is the heading's <section>.
  function sectionHash() {
    var head = document.querySelector(".site-head");
    var top = head ? Math.max(0, head.getBoundingClientRect().bottom) : 0;
    var probe = top + (window.innerHeight - top) * 0.25;
    var els = document.querySelectorAll("main section[id], main [data-twin-id]"), inside = "", above = "";
    for (var i = 0; i < els.length; i++) {
      var el = els[i], box = el.tagName === "SECTION" ? el : (el.closest("section") || el);
      if (!box.getClientRects().length) continue; // hidden (e.g. #reviews before there are any)
      var r = box.getBoundingClientRect(), id = el.getAttribute("data-twin-id") || el.id;
      if (r.top <= probe && r.bottom > probe) inside = id;
      if (r.top <= probe) above = id;
    }
    return (inside || above) ? "#" + (inside || above) : "";
  }

  // returns the URL; navigates unless navigate === false (the toggle lets its own link navigate)
  function switchLanguage(lang, navigate) {
    var a = link(lang);
    if (!a || (lang !== "en" && lang !== "es")) return null;
    saveLang(lang);
    var q = new URLSearchParams(location.search);
    q.delete("lang"); // an old ?lang=es would send the English page straight back to Spanish
    q = q.toString();
    var url = a.getAttribute("href").split(/[?#]/)[0] + (q ? "?" + q : "") + sectionHash();
    if (navigate !== false) location.assign(url);
    return url;
  }
  window.switchLanguage = switchLanguage;

  try {
    [].forEach.call(document.querySelectorAll(".lang a[data-lang]"), function (a) {
      a.addEventListener("click", function () {
        try { var url = switchLanguage(a.getAttribute("data-lang"), false); if (url) a.setAttribute("href", url); }
        catch (err) { /* the link still goes to the other page */ }
      });
    });
  } catch (err) {}

  // Language suggestion bar: only with no lang cookie, when the browser's first "en"/"es" language
  // isn't this page's. Rendered here (never in the HTML), never redirects, never takes focus.
  // Accept -> switchLanguage; close (or Esc) -> lang = this page's language. Either way it's gone for good.
  try {
    if (hasLangCookie()) return;
    var want = null, langs = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || ""];
    for (var i = 0; i < langs.length && !want; i++) {
      var l = String(langs[i]).toLowerCase().split("-")[0];
      if (l === "en" || l === "es") want = l;
    }
    if (!want || want === pageLang || !link(want)) return;
    var T = {
      es: { label: "Sugerencia de idioma", text: "¿Prefieres ver esta página en español?", go: "Ver en español", close: "Cerrar" },
      en: { label: "Language suggestion", text: "Prefer to read this page in English?", go: "View in English", close: "Close" }
    }[want];
    var bar = document.createElement("aside");
    bar.className = "lang-bar"; bar.lang = want; bar.setAttribute("aria-label", T.label);
    var p = document.createElement("p"); p.textContent = T.text;
    var go = document.createElement("button"); go.type = "button"; go.className = "lang-bar-go"; go.textContent = T.go;
    var x = document.createElement("button"); x.type = "button"; x.className = "lang-bar-x"; x.setAttribute("aria-label", T.close); x.innerHTML = '<span aria-hidden="true">&times;</span>';
    bar.appendChild(p); bar.appendChild(go); bar.appendChild(x);
    var root = document.documentElement;
    // --lang-bar-h: the space the bar takes from the bottom edge (offsetTop ignores the entry animation)
    var fit = function () { root.style.setProperty("--lang-bar-h", Math.max(0, window.innerHeight - bar.offsetTop) + "px"); };
    var track = function (choice) { (window.dataLayer = window.dataLayer || []).push({ event: "select_content", content_type: "language_suggestion", item_id: choice, page_language: pageLang }); };
    var onKey = function (e) { if (e.key === "Escape" && !e.defaultPrevented) close(); };
    var close = function () {
      saveLang(pageLang); track("dismiss");
      bar.remove(); root.classList.remove("has-lang-bar"); root.style.removeProperty("--lang-bar-h");
      document.removeEventListener("keydown", onKey); window.removeEventListener("resize", fit);
    };
    go.addEventListener("click", function () { track("accept"); switchLanguage(want); });
    x.addEventListener("click", close);
    var show = function () {
      if (bar.isConnected || hasLangCookie()) return;
      document.addEventListener("keydown", onKey);
      window.addEventListener("resize", fit);
      document.body.appendChild(bar);
      fit(); root.classList.add("has-lang-bar");
    };
    // after the web fonts: the bar sits on the bottom edge, so a font swap changing its height would move it (CLS)
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(show, show); else show();
  } catch (err) {}
})();
/* lang-switch:end */

